npx playwright test --shard=3/4

# Machine 4
npx playwright test --shard=4/4
```

Set `CI=true` on those machines. After each run, **upload `blob-report/` even when tests fail**, using distinct artifact names such as `blob-report-1` through `blob-report-4`.

### Merge in a final CI job

1. Wait for all four shards, including failed ones.
2. Check out the same revision and run `npm ci` to use the same Playwright version.
3. Download all four artifacts, putting their **ZIP files directly inside** one directory:

```text
all-blob-reports/
  report-...-1.zip
  report-...-2.zip
  report-...-3.zip
  report-...-4.zip
```

4. Generate the combined HTML report:

```bash
npx playwright merge-reports --reporter=html ./all-blob-reports
```

5. Publish the resulting **entire `playwright-report/` directory** as the combined report artifact. Open a downloaded copy with:

```bash
npx playwright show-report ./playwright-report
```

Merge **blob reports**, not the shards’ HTML directories. Ensure the final merge job runs despite test failures and that all four shard artifacts are present.

## 1. Retry all three checks as one block

Use **`expect(...).toPass()`**, not three independent polling assertions. Save once, outside the retried block; fetch a fresh profile on every attempt.

```ts
import { test, expect } from '@playwright/test';

test('saving a profile updates every representation', async ({ page }) => {
  const newName = 'Alex Example';

  await page.goto('/profile');
  await page.getByLabel('Name', { exact: true }).fill(newName);
  await page.getByRole('button', { name: 'Save', exact: true }).click();

  await expect(async () => {
    // timeout: 0 makes each DOM check immediate:
    // toPass controls retries of the entire block.
    await expect(page.getByRole('status')).toHaveText(
      `Profile saved for ${newName}`,
      { timeout: 0 },
    );

    await expect(page.getByTestId('avatar')).toHaveAttribute(
      'src',
      `/api/avatar?name=${encodeURIComponent(newName)}`,
      { timeout: 0 },
    );

    // page.request shares the browser context's authentication cookies.
    const response = await page.request.get('/api/profile', {
      headers: { 'Cache-Control': 'no-cache' },
      timeout: 2_000,
    });

    try {
      expect(response.status()).toBe(200);
      expect(await response.json()).toMatchObject({ name: newName });
    } finally {
      await response.dispose();
    }
  }).toPass({
    timeout: 10_000,
    intervals: [100, 250, 500],
  });
});
```

Replace the toast text and avatar URL with your app’s actual contract. **The toast must remain visible long enough for the three checks to pass together.** If it disappears before backend convergence, asserting simultaneous visibility is not a valid requirement; capture the toast separately instead.

## 2. Isolate the server-side account, not just the browser context

`storageState` copies authentication; it does **not** clone the user’s server-side settings. Twenty isolated browser contexts still mutate the same account.

Use **one picker account per worker**, unique across shards, and reset the language before each test because sequential tests on the same worker still share that account.

The example below assumes `/login`, `/settings`, and the shown accessible labels.

### `playwright.config.ts`

```ts
import { defineConfig } from '@playwright/test';

export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  workers: 5, // Fixed: used to partition the account pool across shards.
  timeout: 30_000,

  use: {
    baseURL: process.env.BASE_URL ?? 'http://localhost:3000',
    // Do not configure the old shared picker storageState.
  },

  reporter: process.env.CI
    ? [['blob']]
    : [['html', { open: 'never' }]],
});
```

### `tests/fixtures.ts`

Provide `PICKER_ACCOUNTS_JSON` through your secret store as an array of `{ "email": "...", "password": "..." }` accounts. Four shards × five workers requires **20 distinct accounts**; concurrent CI runs must use separate pools too.

```ts
import {
  test as base,
  expect,
  type BrowserContext,
} from '@playwright/test';

type StorageState = Awaited<ReturnType<BrowserContext['storageState']>>;

type WorkerFixtures = {
  workerStorageState: StorageState;
};

export const test = base.extend<{}, WorkerFixtures>({
  workerStorageState: [
    async ({ browser }, use, workerInfo) => {
      const accounts: Array<{ email: string; password: string }> =
        JSON.parse(process.env.PICKER_ACCOUNTS_JSON ?? '[]');

      const shard = workerInfo.config.shard?.current ?? 1;
      const accountIndex =
        (shard - 1) * 5 + workerInfo.parallelIndex;

      const account = accounts[accountIndex];
      if (!account) {
        throw new Error(`Missing picker account at index ${accountIndex}`);
      }

      const context = await browser.newContext({
        baseURL: workerInfo.project.use.baseURL,
        storageState: { cookies: [], origins: [] },
      });

      let state: StorageState;
      try {
        const page = await context.newPage();
        await page.goto('/login');
        await page.getByLabel('Email', { exact: true }).fill(account.email);
        await page.getByLabel('Password', { exact: true }).fill(account.password);
        await page.getByRole('button', { name: 'Sign in', exact: true }).click();
        await expect(page.getByRole('button', { name: 'Sign out' }))
          .toBeVisible();

        state = await context.storageState();
      } finally {
        await context.close();
      }

      await use(state);
    },
    { scope: 'worker' },
  ],

  storageState: async ({ workerStorageState }, use) => {
    await use(workerStorageState);
  },

  page: async ({ page }, use) => {
    // Establish a known baseline even after a prior test failed.
    await page.goto('/settings');
    await page.getByLabel('Language', { exact: true }).selectOption('en');
    await page.getByRole('button', { name: 'Save', exact: true }).click();
    await expect(page.getByRole('status')).toHaveText('Settings saved');

    await use(page);
  },
});

export { expect };
```

All affected specs must import the fixture:

```ts
import { test, expect } from './fixtures';

test('picker can change language', async ({ page }) => {
  await page.goto('/settings');
  await page.getByLabel('Language', { exact: true }).selectOption('th');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await expect(page.getByRole('status')).toHaveText('Settings saved');
});
```

If settings are applied asynchronously, the reset fixture must also wait for **server-side persistence**, not merely an acknowledgment toast.

## 3. Four shards → blob artifacts → one HTML report

Do **not** merge four HTML directories. Generate **blob reports**, collect their ZIP files, then run `merge-reports`.

Using the config above, this GitHub Actions workflow runs four machines and merges their results:

### `.github/workflows/playwright.yml`

```yaml
name: Playwright

on:
  push:
  pull_request:

jobs:
  test:
    runs-on: ubuntu-latest
    strategy:
      fail-fast: false
      matrix:
        shard: [1, 2, 3, 4]

    env:
      CI: "true"
      BASE_URL: ${{ vars.E2E_BASE_URL }}
      PICKER_ACCOUNTS_JSON: ${{ secrets.PICKER_ACCOUNTS_JSON }}

    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - run: npm ci

      - run: npx playwright install --with-deps

      - name: Run shard
        run: npx playwright test --shard=${{ matrix.shard }}/4

      - name: Upload blob report
        if: ${{ !cancelled() }}
        uses: actions/upload-artifact@v4
        with:
          name: blob-report-${{ matrix.shard }}
          path: blob-report/
          retention-days: 1

  merge:
    if: ${{ !cancelled() }}
    needs: test
    runs-on: ubuntu-latest

    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - run: npm ci

      - name: Download all blob reports
        uses: actions/download-artifact@v4
        with:
          pattern: blob-report-*
          path: all-blob-reports
          merge-multiple: true

      - name: Generate combined HTML report
        run: npx playwright merge-reports --reporter=html ./all-blob-reports

      - name: Upload combined report
        uses: actions/upload-artifact@v4
        with:
          name: playwright-html-report
          path: playwright-report/
          retention-days: 14
```

This assumes the application is already available at `E2E_BASE_URL`; otherwise configure Playwright’s `webServer` to start it on each machine. Use the same lockfile/Playwright version on all shard and merge jobs. Blob filenames include shard information by default—retain those names when collecting them.

## 1. Retry the entire group with `expect().toPass()`

Save **outside** the retried block so retries do not submit the form again. Fetch the profile **inside** it so each attempt reads fresh backend state.

```ts
import { test, expect } from '@playwright/test';

test('saves the profile', async ({ page }) => {
  const newName = 'Alex Updated';

  await page.goto('/profile');
  await page.getByLabel('Name', { exact: true }).fill(newName);
  await page.getByRole('button', { name: 'Save', exact: true }).click();

  await expect(async () => {
    await expect(page.getByRole('status')).toHaveText(
      `Profile saved for ${newName}`,
      { timeout: 1_000 },
    );

    await expect(page.getByTestId('avatar')).toHaveAttribute(
      'src',
      `/api/avatar?name=${encodeURIComponent(newName)}`,
      { timeout: 1_000 },
    );

    // Shares the browser context's authentication cookies.
    const response = await page.request.get('/api/profile');
    expect(response.ok()).toBeTruthy();
    expect(await response.json()).toMatchObject({ name: newName });
  }).toPass({
    timeout: 10_000,
    intervals: [250, 500, 1_000],
  });
});
```

Adapt the toast text, avatar URL format, and JSON field to your application. **Set `toPass`’s timeout explicitly**; its default is `0`, not the configured assertion timeout.

If the toast disappears before the backend converges, this combined check cannot reliably succeed. Keep the toast visible long enough, or verify the transient notification separately.

## 2. Isolate the server-side account, not just browser storage

`storageState` creates separate browser sessions, **not separate backend users**. All 20 tests are racing to update the same account.

Give each parallel worker a different picker account. Provision authenticated state files for those accounts, then select the appropriate file:

```ts
// fixtures.ts
import { test as base, expect } from '@playwright/test';
import path from 'node:path';

export const test = base.extend({
  storageState: async ({}, use, testInfo) => {
    const shard = testInfo.config.shard?.current ?? 1;

    await use(path.resolve(
      'playwright/.auth',
      `picker-${testInfo.project.name}-s${shard}-w${testInfo.parallelIndex}.json`,
    ));
  },
});

export { expect };
```

```ts
// playwright.config.ts
import { defineConfig } from '@playwright/test';

export default defineConfig({
  fullyParallel: true,
  workers: 4,
  use: {
    baseURL: process.env.BASE_URL ?? 'http://localhost:3000',
  },
  projects: [
    { name: 'chromium', use: { browserName: 'chromium' } },
  ],
  reporter: process.env.CI ? 'blob' : 'html',
});
```

For one project and four shards, provision **16 distinct accounts**, one per `(project, shard, parallelIndex)`. Each state file must authenticate a **different user**—copying the same user's state into different files does not fix it. Concurrent CI runs also need separate account pools.

Import the custom fixture in every affected spec:

```ts
import { test, expect } from './fixtures';
```

Also reset the worker account’s language **before every test**, because sequential tests on the same worker still share backend state. For example, assuming this is your settings endpoint:

```ts
test.beforeEach(async ({ request }) => {
  const response = await request.patch('/api/profile', {
    data: { language: 'en' },
  });
  expect(response.ok()).toBeTruthy();
});
```

If settings apply asynchronously, poll until the reset is observable before starting the test.

**Fallback if only one account is available:** run all tests using that account in a single job with `workers: 1`, and reset language before each test. Serializing just one file does not prevent other files or CI shards from changing the account.

## 3. Produce blob reports per shard, then merge them into HTML

Use the `reporter` setting above. Each CI machine runs one shard:

```bash
# Machine 1
npx playwright test --shard=1/4

# Machine 2
npx playwright test --shard=2/4

# Machine 3
npx playwright test --shard=3/4

# Machine 4
npx playwright test --shard=4/4
```

With `CI=true`, each produces `blob-report/*.zip`. Upload those files even when tests fail, download all four artifacts into one directory, then run:

```bash
npx playwright merge-reports --reporter=html ./all-blob-reports
```

Here is the complete GitHub Actions orchestration:

```yaml
# .github/workflows/playwright.yml
name: Playwright
on: [push, pull_request]

jobs:
  test:
    runs-on: ubuntu-latest
    strategy:
      fail-fast: false
      matrix:
        shard: [1, 2, 3, 4]

    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - run: npm ci
      - run: npx playwright install --with-deps

      # Start your app and provision the shard's distinct picker
      # accounts/storageState files here.

      - run: npx playwright test --shard=${{ matrix.shard }}/4
        env:
          CI: 'true'

      - uses: actions/upload-artifact@v4
        if: ${{ !cancelled() }}
        with:
          name: blob-report-${{ matrix.shard }}
          path: blob-report
          retention-days: 1

  merge:
    needs: test
    if: ${{ !cancelled() }}
    runs-on: ubuntu-latest

    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - run: npm ci

      - uses: actions/download-artifact@v4
        with:
          pattern: blob-report-*
          path: all-blob-reports
          merge-multiple: true

      - run: npx playwright merge-reports --reporter=html ./all-blob-reports

      - uses: actions/upload-artifact@v4
        with:
          name: playwright-html-report
          path: playwright-report
          retention-days: 14
```

Use the same locked Playwright version on all shards and the merge job. **Merge blob reports, not independently generated HTML reports.**
